            aWandererA = aWandererA ^ ((RotL64(aScatter, 18U) + RotL64(aOrbiterG, 47U)) + aOrbiterJ);
            aWandererB = aWandererB + ((((RotL64(aPrevious, 11U) + aOrbiterG) + RotL64(aOrbiterD, 36U)) + RotL64(aCarry, 19U)) + aPhaseCWandererUpdateSaltC[((aIndex + 26U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aIngress, 37U) + aOrbiterB) + RotL64(aOrbiterD, 43U));
