            aOrbiterD = RotL64((aOrbiterD * 0x2E3A78C7BE4B7DA1ULL), 37U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterC) + 0x854EDAA77F7A98C2ULL) + aPhaseCOrbiterUpdateSaltD[((aIndex + 13U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0xCBD14D3CA9DBEE66ULL;
