            aWandererD = aWandererD + ((((RotL64(aIngress, 19U) + RotL64(aOrbiterB, 35U)) + aOrbiterJ) + RotL64(aCarry, 27U)) + aPhaseCWandererUpdateSaltC[((aIndex + 15U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aCross, 57U) + aOrbiterE) + RotL64(aOrbiterJ, 57U));
