            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x76474BE8D256C4EBULL) + aPhaseBOrbiterUpdateSaltD[((aIndex + 11U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0xB034891D80D60E07ULL;
