            //
            aIngress = (RotL64(aIceLaneA[((aIndex + 11656U)) & S_BLOCK1], 18U) ^ RotL64(aHeartLaneC[((aIndex + 14763U)) & S_BLOCK1], 5U));
            aIngress ^= (RotL64(aWindLaneA[((aIndex + 9538U)) & S_BLOCK1], 57U) ^ RotL64(aSpiritLaneB[((S_BLOCK1 - aIndex + 12374U)) & S_BLOCK1], 37U));
            aIngress = TwistMix64::DiffuseA(aIngress);
            //
            aCross = (RotL64(aHeartLaneA[((S_BLOCK1 - aIndex + 16300U)) & S_BLOCK1], 21U) ^ RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 9149U)) & S_BLOCK1], 12U));
            aCross ^= (RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 12309U)) & S_BLOCK1], 41U) ^ RotL64(aSpiritLaneD[((aIndex + 10065U)) & S_BLOCK1], 3U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aPrevious, 5U) ^ RotL64(aCarry, 56U)) ^ (RotL64(aIngress, 39U) + RotL64(aCross, 27U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterG = (aWandererB + RotL64(aScatter, 57U)) + 0xCF9FB1E733A344A2ULL;
            aOrbiterH = ((aWandererJ + RotL64(aPrevious, 3U)) + RotL64(aCarry, 13U)) + 0xBAC8542BF89280A7ULL;
            aOrbiterB = (aWandererA + RotL64(aCross, 37U)) + 0x1352C04662F9B7D7ULL;
            aOrbiterK = ((aWandererE + RotL64(aIngress, 19U)) + 0x53A922BE19605FA3ULL) + aPhaseCOrbiterAssignSaltD[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aCross, 48U)) + RotL64(aCarry, 53U)) + 0x5569B2E0395B8261ULL;
            aOrbiterA = ((aWandererG + RotL64(aScatter, 29U)) + 0xB79B491DAA2A996CULL) + aPhaseCOrbiterAssignSaltA[((aIndex + 12U)) & S_SALT1];
            aOrbiterD = ((aWandererD + RotL64(aIngress, 11U)) + RotL64(aCarry, 41U)) + 0x7155BA5C2B8A2E8CULL;
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0xC8315E0448478683ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0x6F2860C2D8522EADULL) ^ aPhaseCOrbiterUpdateSaltB[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xBAB4AEA37AFBB995ULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0xC4EB0B550D3A3AF1ULL;
