            aOrbiterK = RotL64((aOrbiterK * 0x22F5FCF515CC6137ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0x29423A6E08235D11ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x39EDF1140A91ECBDULL;
            aOrbiterD = RotL64((aOrbiterD * 0x098792B7AA15F927ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xA60AF05E81199B58ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x7DD5B914BCFD9119ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x72AEE6B1C71E60C9ULL), 21U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xC22939E22853AF5AULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0xB8E8BE835A088C67ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x597CED9F8252ACCBULL), 13U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0x5A9DBF9C24C059DEULL) + aPhaseCOrbiterUpdateSaltE[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterC) ^ 0x4CEB2B86D362E563ULL) ^ aPhaseCOrbiterUpdateSaltC[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xBE54F5E0F607D961ULL), 3U);
            //
            aIngress = RotL64(aOrbiterB, 13U) ^ aOrbiterG;
