            aOrbiterG = ((aWandererI + RotL64(aIngress, 51U)) + 0xA729A140F5C112E8ULL) + aPhaseAOrbiterAssignSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterK = (aWandererF + RotL64(aPrevious, 60U)) + 0xE5ECAD25781A04EAULL;
            aOrbiterA = (aWandererH + RotL64(aScatter, 19U)) + 0x955F574ABEBAD6B5ULL;
            aOrbiterC = ((aWandererJ + RotL64(aIngress, 37U)) + RotL64(aCarry, 27U)) + 0x526DEB7765F3A8C9ULL;
            aOrbiterJ = (aWandererA + RotL64(aCross, 29U)) + 0xBCB8BD6B857A0C19ULL;
            aOrbiterH = (((aWandererE + RotL64(aScatter, 43U)) + RotL64(aCarry, 41U)) + 0xE407B7F0E6C9EC4EULL) + aPhaseAOrbiterAssignSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x8CE0A4752BDF1EDDULL;
