            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0xBCD68768F150E92FULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterC) ^ 0x25DDCF8709ED7CDFULL) ^ aPhaseAOrbiterUpdateSaltF[((aIndex + 13U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xB06376C44BEBB21FULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x9B780A993F722AE7ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x63AE310E6AC19D6AULL;
