            //
            aOrbiterK = ((aOrbiterK + aOrbiterA) + 0x9D80EB3FB3B02E2FULL) + aPhaseAOrbiterUpdateSaltD[((aIndex + 29U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0xD9CCB3975375D6A8ULL) ^ aPhaseAOrbiterUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1];
