            aOrbiterJ = (((aWandererD + RotL64(aPrevious, 56U)) + RotL64(aCarry, 11U)) + 0x34424C9CE06CFCF1ULL) + aPhaseDOrbiterAssignSaltD[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterB = ((aWandererE + RotL64(aIngress, 47U)) + RotL64(aCarry, 51U)) + 0xAFCFA9F5F21C29F6ULL;
            aOrbiterH = ((aWandererA + RotL64(aCross, 23U)) + RotL64(aCarry, 37U)) + 0x208DCE4FB460719AULL;
            aOrbiterC = ((aWandererJ + RotL64(aPrevious, 13U)) + 0xF5BF30A3C36C47D2ULL) + aPhaseDOrbiterAssignSaltC[(((31U - aIndex) + 8U)) & S_SALT1];
