            aOrbiterC = (aOrbiterC + aOrbiterA) + 0x102FC95C45AAF948ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterC) ^ 0xECAB99089505F312ULL) ^ aPhaseDOrbiterUpdateSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
